SELECT 
FROM payment_cancel AS pc
WHERE pc.transaction_key = #{transactionKey}

SELECT 
FROM payment_cancel AS pc
WHERE pc.status = #{status}
  AND pc.created_at >= #{from} AND pc.created_at < #{to}

SELECT 
FROM payment_cancel AS pc
WHERE pc.status = #{status}
  AND pc.canceled_at >= #{from} AND pc.canceled_at < #{to}

mapper.update:
UPDATE payment_cancel
SET status = #{toStatus},
    transaction_key = #{transactionKey},
    canceled_at = #{canceledAt}
WHERE id = #{id}
  AND status = #{fromStatus}

UPDATE payment_cancel
SET last_error = #{lastError}
WHERE id = #{id}
